# Sàng: gạch bội của 2, rồi của 3, rồi của 5, rồi của 7.
n = 100
con_lai = [True] * (n + 1)
i = 2
while i * i <= n:
    if con_lai[i]:
        boi = i + i
        while boi <= n:
            con_lai[boi] = False
            boi = boi + i
    i = i + 1

dem = 0
for x in range(2, n + 1):
    if con_lai[x]:
        print(x, end=" ")
        dem = dem + 1
        if dem % 10 == 0:
            print()
print()
print("Còn lại", dem, "số.")

# Gạch bội của 2 trong bảng 20 ô.
con_lai = [True] * 21
boi = 4
while boi <= 20:
    con_lai[boi] = False
    boi = boi + 2
for x in range(2, 21):
    if con_lai[x]:
        print(x, end=" ")
print()

